var maxN = 5, maxFraction = 0, scurrency = 'đ', shippingdate = null;
var weekday = new Array(7);
weekday[0] = "Sunday";
weekday[1] = "Monday";
weekday[2] = "Tuesday";
weekday[3] = "Wednesday";
weekday[4] = "Thursday";
weekday[5] = "Friday";
weekday[6] = "Saturday";
function formatMoney(m) {
    var nStr = parseFloat(m).toLocaleString('en-US', {
        maximumFractionDigits: maxFraction
    });
    return nStr + scurrency;
}

function afterloadOrderHtml() {
    $('.order-plus-btn').click(function(){
        var n = $(this).data('n');
        var max = parseInt($('#product'+n+'container').find('input[name="quantity"]').attr('max'));
        var qty = parseInt($('#product'+n+'container').find('input[name="quantity"]').val());
        if (qty < max) {
            qty++;
            $('#product'+n+'container').find('input[name="quantity"]').val(qty);
        }
    });
    $('.order-minus-btn').click(function(){
        var n = $(this).data('n');
        var min = parseInt($('#product'+n+'container').find('input[name="quantity"]').attr('min'));
        var qty = parseInt($('#product'+n+'container').find('input[name="quantity"]').val());
        if (qty > min) {
            qty--;
            $('#product'+n+'container').find('input[name="quantity"]').val(qty);
        }
    });
    $('.add-to-cart-btn').on('click',function(){
        var n = $(this).data('n');
        var qty = parseInt($('#product'+n+'container').find('input[name="quantity"]').val());
        var productid = $('#product'+n+'container').data('productid');
        var productpriceid = parseInt($('#product'+n+'container').find('select[name="productpriceid"]').val());
        var mOrderItem = {};
        mOrderItem.productpriceid = productpriceid;
        mOrderItem.productcode = productid + 'X' + productpriceid;
        mOrderItem.productid = productid;
        mOrderItem.quantity = qty;
        mOrderItem.shippingdate = shippingdate;
        if (mOrderItem.quantity > 0) {
            $.ajax({
                url: '/ajax/add-to-cart.json',
                type: "POST",
                data: JSON.stringify(mOrderItem),
                dataType: "json",
                contentType: "application/json",
                success: function (result) {
                    ENET_LEAD_SERVICE.shoppingCartService.updateCartWithResutl(result, true);
                }
            });
        }
    });
}
function loadProductsForOrder() {
    var cat = '';
    if ($('.cat-link.active').length) {
        cat = $('.cat-link.active').data('cat');
    } else {
        $('.cat-link:first').addClass('active');
        cat = $('.cat-link:first').data('cat');
    }
    var spdate  = $('.shippingdate-info').html();
    if (spdate != '' && cat != '') {
        var attMaxN = $('#ajax-products-for-order').attr('maxN');
        if (attMaxN != null && attMaxN != '') {
            maxN = parseInt(attMaxN);
        }
        var day = moment(spdate, 'DD/MM/YYYY hh:mm').toDate().getDay();
        var query = weekday[day];
        $.ajax({
            url: '/ajax/'+maxN+'/products-for-order.html?query='+ query + '&cat='+cat,
            type: 'GET',
            contentType: "application/json",
            success: function(orderhtml) {
                $('#ajax-products-for-order').html(orderhtml);
                scurrency = $('.scurrency').html();
                if (scurrency == 'USD') {
                    maxFraction = 2;
                }
                afterloadOrderHtml();
            }
        });
    }
}
$(document).ready(function() {
    $('#selectShippingdateModal .shippingdate').flatpickr({
        enableTime: true,
        dateFormat: "d/m/Y H:i",
        minTime: "06:00",
        maxTime: "22:00"
    });
    if ($('.shippingdate-info').html() == '') {
        $('#selectShippingdateModal').modal('show');
    }
    $('.continue-shippingdate-btn').on('click',function(){
        $('#selectShippingdateModal').modal('hide');
        var spdate  = $('#selectShippingdateModal .shippingdate').val();
        if (spdate != '' && spdate != shippingdate) {
            shippingdate = spdate;
            $('.shippingdate-info').html(spdate);
            loadProductsForOrder();
            $.ajax({
                url: '/ajax/reset-cart.json?shippingdate='+encodeURIComponent(shippingdate),
                type: "GET",
                contentType: "application/json",
                success: function (result) {
                    ENET_LEAD_SERVICE.shoppingCartService.updateCartWithResutl(result);
                }
            });
        } else {
            $('#selectShippingdateModal .shippingdate').focus();
        }
    });
    $('.cat-link').on('click',function(){
        $('.cat-link').removeClass('active');
        $(this).addClass('active');
        if ($('.shippingdate-info').html() == '') {
            $('#selectShippingdateModal').modal('show');
        } else {
            loadProductsForOrder();
        }
    });
    $('.select-a-date').on('click',function(){
        $('#selectShippingdateModal').modal('show');
    });
});
